#include <bits/stdc++.h>
using namespace std;

int main()
{
  int N;
  cin >> N;
  vector<int> A(N);
  for (int i = 0; i < N; i++)
    cin >> A[i];

  map<int, vector<int>> mps;
  for (int i = 0; i < N; i++)
    mps[A[i]].push_back(i);

  vector<int> dp(N, 1);
  for (int i = 0; i < N; i++)
  {
    const auto &vec = mps[A[i] + 1];
    int k = ranges::lower_bound(vec, i) - vec.begin();
    if (k < (int)vec.size())
    {
      int j = vec[k];
      dp[j] = max(dp[j], dp[i] + 1);
    }
  }
  cout << ranges::max(dp) << endl;
}
